@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Unbounded:wght@400;500;600;700&display=swap');
:root{--ink:#eeece7;--muted:#8d8a85;--line:#373634;--panel:#191919;--bg:#111110;--gold:#c7a86c;--red:#a64d46;--green:#718269;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Unbounded',sans-serif}*{box-sizing:border-box}html,body{margin:0;min-height:100%;background:#0d0e0e;color:var(--ink);font-family:var(--sans);overscroll-behavior:none}body{padding:22px;display:grid;place-items:center}.game-shell{width:min(1440px,100%);background:var(--bg);border:1px solid #2c2c2a;box-shadow:0 24px 100px #0009}.topbar{height:60px;padding:0 25px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);background:#141414}.brand{display:flex;align-items:center;gap:11px;color:var(--ink);font:600 11px var(--display);letter-spacing:.13em;text-decoration:none}.brand i{font-style:normal;color:var(--gold)}.brand-mark{font-size:21px;color:var(--gold)}.chapter{font:10px var(--mono);letter-spacing:.12em;color:#aaa}.live-dot{display:inline-block;width:6px;height:6px;margin-right:8px;border-radius:50%;background:#879071;box-shadow:0 0 9px #879071}.top-actions{display:flex;gap:8px}.icon-btn{border:1px solid #383735;background:transparent;color:#aaa;height:29px;min-width:34px;padding:0 9px;font:11px var(--mono);cursor:pointer}.icon-btn:hover,.text-btn:hover{color:var(--gold);border-color:#756344}.game-grid{display:grid;grid-template-columns:minmax(0,1fr) 335px;min-height:650px}.play-column{padding:17px 17px 0 20px;min-width:0}.scene-frame{height:min(68vh,670px);min-height:470px;position:relative;overflow:hidden;background:#1a211e;border:1px solid #33332f;isolation:isolate}.scene-frame canvas{position:absolute;inset:0;width:100%;height:100%;image-rendering:pixelated}.scene-vignette{position:absolute;inset:0;background:linear-gradient(180deg,#0e111144 0%,transparent 23%,transparent 64%,#090a0bdc 100%),linear-gradient(90deg,#090a0b55,transparent 28%,transparent 78%,#090a0b55);pointer-events:none}.scene-topline{position:absolute;top:18px;left:20px;right:20px;display:flex;justify-content:space-between;align-items:center}.location{display:flex;gap:11px;align-items:center;text-shadow:0 2px 6px #000}.location-icon{font-size:22px;color:var(--gold)}.location b{display:block;font:11px var(--display);letter-spacing:.11em}.location small{display:block;color:#b8b2a7;font:9px var(--mono);letter-spacing:.11em;margin-top:5px}.weather{font:9px var(--mono);letter-spacing:.1em;color:#bbb;background:#10121288;border:1px solid #ffffff20;padding:8px 10px}.scene-caption{position:absolute;bottom:26px;left:28px;max-width:390px;text-shadow:0 2px 10px #000}.caption-kicker{display:block;font:9px var(--mono);letter-spacing:.15em;color:#d0b779;margin-bottom:12px}.scene-caption strong{font:500 clamp(22px,3vw,38px)/1.2 var(--display);letter-spacing:-.04em}.scene-caption p{font-size:12px;color:#c5c0b9;margin:11px 0 0}.canvas-prompt{position:absolute;bottom:21px;right:21px;color:#c1bdb5;font:9px var(--mono);letter-spacing:.06em;text-shadow:0 1px 5px #000}.canvas-prompt span{color:var(--gold);padding:0 5px}.game-controls{height:62px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}.objective{display:flex;align-items:center;gap:11px}.objective-icon{font-size:19px;color:var(--gold)}.objective small,.stat-line,.section-heading,.panel-title,.raid-head,.raid-foot{font:9px var(--mono);letter-spacing:.1em}.objective small{display:block;color:#87847d;margin-bottom:4px}.objective b{font-size:12px;font-weight:500}.control-hint{color:#777;font:9px var(--mono);display:flex;align-items:center;gap:5px}.control-hint kbd{font:9px var(--mono);color:#ccc;border:1px solid #4a4945;padding:3px 5px;border-radius:2px}.pause-btn{background:transparent;border:1px solid #444;color:#aaa;width:31px;height:31px;cursor:pointer}.side-panel{padding:21px 20px 17px;background:#171716;border-left:1px solid var(--line)}.panel-title,.section-heading{display:flex;align-items:center;justify-content:space-between;color:#c6c1b6}.panel-title{padding-bottom:14px;border-bottom:1px solid var(--line);font-size:10px}.panel-title em{color:var(--gold);font-style:normal}.text-btn{border:0;background:none;color:#a49f94;font:9px var(--mono);letter-spacing:.07em;cursor:pointer;padding:4px}.hero-card{display:flex;gap:13px;padding:17px 0 18px;border-bottom:1px solid var(--line)}.portrait{width:91px;height:110px;position:relative;overflow:hidden;flex-shrink:0;background:linear-gradient(150deg,#343b35,#171b1a 56%,#25241f);border:1px solid #49473e;display:grid;place-items:center}.portrait:before,.portrait:after{content:'';position:absolute;border-radius:50%;background:#bea2701b;filter:blur(1px)}.portrait:before{width:82px;height:82px;top:-34px;right:-20px}.portrait:after{height:90px;width:50px;bottom:-45px;left:-15px;background:#c1895b22}.portrait-halo{position:absolute;width:43px;height:43px;border:1px solid #bca26a66;border-radius:50%;top:17px}.portrait-figure{z-index:1;font-size:43px;color:#a99a78;text-shadow:0 0 20px #c4a76566}.portrait-label{position:absolute;bottom:7px;left:7px;font:7px var(--mono);letter-spacing:.11em;color:#aaa}.portrait-level{position:absolute;top:7px;right:7px;font:7px var(--mono);color:var(--gold)}.hero-info{flex:1;min-width:0;padding-top:1px}.hero-name{font:10px var(--display);letter-spacing:.02em;display:flex;justify-content:space-between;align-items:center}.hero-name button{background:none;border:0;color:#888;cursor:pointer}.hero-class{color:#9e998f;font:8px var(--mono);letter-spacing:.07em;margin:7px 0 13px}.stat-line{display:flex;justify-content:space-between;color:#918d84;font-size:8px;margin-bottom:5px}.stat-line b{color:#d5d0c6;font-weight:400}.meter{height:4px;background:#33312d;position:relative;margin-bottom:10px}.meter i{height:100%;display:block;transition:width .25s}.hp-meter i{background:linear-gradient(90deg,#8b4039,#c36b5a)}.faith-meter{background:linear-gradient(90deg,#744640,#3a3933 50%,#3f5941)}.faith-meter i{position:absolute;top:0;left:50%;height:100%;background:var(--gold);z-index:1}.faith-mid{position:absolute;left:50%;top:-2px;height:8px;border-left:1px solid #ddd7ca;z-index:2}.faith-label{margin-top:8px}.section-heading{margin:16px 0 9px;font-size:9px}.weapon-card{width:100%;height:52px;background:#20201e;border:1px solid #3c3a34;color:var(--ink);display:flex;align-items:center;text-align:left;padding:7px 10px;gap:11px;cursor:pointer}.weapon-card:hover{border-color:#8b7651}.weapon-icon{display:grid;place-items:center;width:34px;height:34px;background:#302d27;color:var(--gold);font-size:19px}.weapon-details{display:flex;flex-direction:column;gap:4px;flex:1}.weapon-details b{font:9px var(--display);letter-spacing:.04em}.weapon-details small{color:#99958d;font:8px var(--mono)}.weapon-chevron{color:#aaa}.ability-row{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-top:8px}.ability{height:57px;background:#1d1d1b;border:1px solid #33322e;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;color:#bbb}.ability-glyph{font-size:14px;color:var(--gold)}.ability b{font:7px var(--mono);letter-spacing:.03em}.ability small{font:6px var(--mono);color:#777}.village-heading{margin-top:17px}.time-chip{color:#d7be82;border:1px solid #5b523e;padding:4px 6px;font-size:8px}.village-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:5px}.building{height:44px;background:#20201e;border:1px solid #34332f;color:#c2bdb2;display:flex;align-items:center;gap:8px;padding:0 8px;cursor:pointer;text-align:left}.building span{font-size:15px;color:#9d967d}.building b{font:7px var(--mono);letter-spacing:.03em}.building:hover,.building.active{border-color:#9c8258;background:#292720;color:#eee}.building.active span{color:var(--gold)}.raid-card{margin-top:14px;padding:10px 11px;background:#20201e;border:1px solid #3c3932}.raid-head,.raid-foot{display:flex;justify-content:space-between;color:#99958c;font-size:8px}.raid-head span:last-child{color:#e0d9ca}.raid-head i{font-style:normal;color:#7f7b73}.raid-progress{height:3px;background:#363430;margin:9px 0 8px}.raid-progress i{height:100%;width:0;display:block;background:var(--gold);transition:width .4s}.raid-foot{font-size:7px}.raid-foot span:last-child{color:var(--gold)}.bottom-bar{height:34px;padding:0 20px;border-top:1px solid #2d2c29;display:flex;align-items:center;justify-content:space-between;color:#68665f;font:8px var(--mono);letter-spacing:.08em}.bottom-bar i{font-style:normal;color:#a18856}.modal-backdrop{position:fixed;inset:0;z-index:20;background:#080909c9;display:grid;place-items:center;padding:16px;backdrop-filter:blur(5px)}.modal-backdrop.hidden,.hidden{display:none!important}.modal{width:min(540px,100%);position:relative;background:#191918;border:1px solid #62563f;box-shadow:0 24px 90px #000b;padding:30px}.modal-close{position:absolute;right:15px;top:12px;border:0;background:none;color:#aaa;font-size:26px;cursor:pointer}.modal-eyebrow{font:9px var(--mono);letter-spacing:.16em;color:var(--gold);margin-bottom:13px}.modal h2{font:500 24px var(--display);margin:0 0 12px}.modal p{color:#aaa69e;font-size:13px;line-height:1.6}.modal-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:22px}.action-btn{border:1px solid #62563f;background:#29271f;color:#eee4d0;padding:11px 15px;font:9px var(--mono);letter-spacing:.08em;cursor:pointer}.action-btn:hover,.action-btn.primary{background:#a78a55;border-color:#a78a55;color:#10100f}.action-btn.secondary{background:transparent;border-color:#484640;color:#bbb}.modal-list{list-style:none;padding:0;margin:18px 0}.modal-list li{border-top:1px solid #333;padding:11px 0;color:#cac5ba;font-size:12px;display:flex;justify-content:space-between}.modal-list span{color:#89847a}.toast{position:fixed;bottom:25px;left:50%;transform:translate(-50%,20px);opacity:0;z-index:30;background:#29271f;border:1px solid #796949;color:#e8dfce;padding:10px 16px;font:10px var(--mono);letter-spacing:.06em;transition:.25s;pointer-events:none}.toast.show{transform:translate(-50%,0);opacity:1}.boss-banner{position:absolute;top:83px;left:50%;transform:translateX(-50%);text-align:center;min-width:220px;padding:10px 18px;background:#190f0fce;border-top:1px solid #985248;border-bottom:1px solid #985248}.boss-banner span{display:block;font:8px var(--mono);color:#d38b75;letter-spacing:.2em;margin-bottom:4px}.boss-banner b{font:11px var(--display);letter-spacing:.1em}.combat-flash{position:absolute;inset:0;pointer-events:none}.combat-flash.hit{animation:flash .2s}@keyframes flash{50%{background:#ce51401f}}.mobile-stick,.mobile-actions,.touch-interact{display:none}
@media(max-width:980px){body{padding:0}.game-shell{border:0;width:100%;min-height:100dvh}.game-grid{grid-template-columns:minmax(0,1fr) 300px}.play-column{padding:12px 12px 0}.side-panel{padding:18px 15px}.scene-frame{min-height:430px;height:66vh}.bottom-bar{font-size:7px}.ability-row{gap:3px}.ability b{font-size:6px}.building{padding:0 5px;gap:5px}}
@media(max-width:720px){body{display:block}.game-shell{min-height:100dvh;display:flex;flex-direction:column}.topbar{height:52px;padding:0 13px}.brand{font-size:9px;gap:6px}.brand-mark{font-size:17px}.chapter{font-size:8px}.top-actions{gap:4px}.icon-btn{height:27px;min-width:29px;padding:0 6px;font-size:9px}.game-grid{display:flex;flex-direction:column;min-height:unset}.play-column{padding:8px 8px 0}.scene-frame{height:56vh;min-height:390px;max-height:620px}.scene-topline{top:12px;left:12px;right:12px}.location b{font-size:9px}.location small{font-size:7px}.weather{font-size:7px;padding:6px}.scene-caption{left:16px;bottom:17px}.scene-caption strong{font-size:25px}.scene-caption p{font-size:10px}.caption-kicker{font-size:8px;margin-bottom:8px}.canvas-prompt{display:none}.game-controls{height:54px}.objective{gap:7px}.objective b{font-size:10px}.objective small{font-size:7px}.control-hint{display:none}.pause-btn{width:29px;height:29px}.side-panel{border-left:0;border-top:1px solid var(--line);padding:14px 12px 18px;display:grid;grid-template-columns:1fr 1fr;gap:0 14px}.panel-title{grid-column:1/-1}.hero-card{grid-column:1/-1;padding:12px 0}.section-heading:nth-of-type(2){grid-column:1/-1}.weapon-card,.ability-row{grid-column:1/-1}.village-heading{grid-column:1/-1}.village-grid{grid-column:1/-1}.raid-card{grid-column:1/-1;margin-top:10px}.bottom-bar{height:auto;min-height:30px;padding:7px 10px;font-size:6px;gap:8px}.bottom-bar span:nth-child(2){display:none}.mobile-stick{display:block;position:absolute;bottom:18px;left:15px;width:100px;height:100px;touch-action:none;opacity:.82}.stick-ring{position:absolute;inset:9px;border-radius:50%;border:1px solid #d6ceb866;background:#25252066;box-shadow:inset 0 0 18px #0007}.stick-knob{position:absolute;width:39px;height:39px;left:50%;top:50%;transform:translate(-50%,-50%);border-radius:50%;background:#afa27b88;border:1px solid #e4d5ad99}.mobile-actions{display:flex;position:absolute;bottom:17px;right:14px;align-items:flex-end;gap:8px}.touch-action{border-radius:50%;width:55px;height:55px;background:#201f1bd9;border:1px solid #c6ae7a99;color:#e3d6b8;font-size:20px;touch-action:none;box-shadow:0 4px 12px #0008}.touch-action small{display:block;font:6px var(--mono);margin-top:2px;color:#d4c7a6}.touch-action.attack{width:68px;height:68px;background:#50332ebf;border-color:#d28369}.touch-action.skill{background:#333329dc}.touch-interact{display:block;position:absolute;bottom:18px;left:50%;transform:translateX(-50%);pointer-events:none}.touch-interact button{pointer-events:auto;background:#181917e8;color:#e7d8b5;border:1px solid #b49b69;padding:10px 13px;font:8px var(--mono);letter-spacing:.06em}.touch-interact button b{color:var(--gold);margin-left:7px}.modal{padding:25px 20px}.modal h2{font-size:20px}}
@media(max-width:380px){.chapter{display:none}.scene-frame{min-height:365px}.scene-caption strong{font-size:22px}.mobile-stick{width:85px;height:85px;left:8px}.touch-action{width:48px;height:48px}.touch-action.attack{width:60px;height:60px}.mobile-actions{right:8px}.building{height:40px}.building b{font-size:6px}}

(() => {
  const $ = (s) => document.querySelector(s);
  const canvas = $('#scene'), ctx = canvas.getContext('2d');
  const state = {
    phase:'day', day:1, raid:1, hero:{x:.5,y:.62,hp:100,maxHp:100,faith:20,name:'EL PEREGRINO'},
    enemies:[], projectiles:[], kills:0, stage:0, unlocked:false, agatha:false, weapon:0, preset:0,
    running:false, free:false, paused:false, sound:true, lang:'es', combatTimer:0, attacks:0, combo:0, lastAttack:0,
    bossHp:0, bossMax:0, interactCooldown:0, modal:null, npcs:{agatha:0,innkeeper:0}, rank:'—',
    keys:{}, stick:{x:0,y:0}, dodge:0, invuln:0, toastTimer:null
  };
  const weapons=[['HOZ DE VIGILIA','PRESAGIO'],['ESPADA DE CENIZA','PURIFICACIÓN'],['MARTILLO DE CAMPANA','RESONANCIA'],['DAGAS DEL PENITENTE','LAMENTO'],['LÁTIGO DE ESPINAS','SACRIFICIO'],['ESTACA DE PLATA','LUCERO'],['LIBRO DE SALMOS','LETANÍA'],['GUADAÑA DEL ABISMO','ÚLTIMO RITO']];
  const raids=['EL BOSQUE QUE RESPIRA','LA CRIPTA SUMERGIDA','EL MOLINO ROJO','EL CAMINO DE LOS CUERVOS','LA MINA DE LOS LAMENTOS','EL PUEBLO ENTERRADO','EL MONASTERIO CIEGO','EL ABISMO'];
  const bosses=['EL ABAD HUECO','LA NOVIA DE BARRO','EL MOLINERO','EL CIervo NEGRO','LA MADRE DE LA MINA','EL PEREGRINO ROTO','EL SANTO CIEGO','EL ABISMO'];
  const buildings={iglesia:['Iglesia de Santa Vela','Hermana Agatha espera junto al altar. La campana no ha dejado de vibrar desde el alba.'],forja:['Forja de Iván','El herrero afila tu arma. Cada incursión deja una marca nueva en el acero.'],botica:['Botica de Mara','Frascos de ajenjo y sal consagrada. Recuperas 20 puntos de vitalidad.'],posada:['La Última Posada','El fuego está encendido. Los viajeros hablan de luces bajo el bosque.'],archivo:['Archivo parroquial','Un mapa viejo señala ocho lugares donde la tierra se ha abierto.'],cementerio:['Cementerio','Las lápidas más recientes están vacías. La tierra removida aún está tibia.'],mercado:['Mercado','La gente intercambia pan, velas y rumores. Nada tiene un precio esta noche.'],establo:['Establo','Tu caballo, Ceniza, conoce el camino a la frontera.'],puerta:['Puerta norte','Más allá de la empalizada, el bosque contiene el aliento.']};
  const texts={es:{day:'DÍA',night:'NOCHE',interact:'HABLAR / USAR',objective:'OBJETIVO ACTUAL',switch:'Cambiar idioma'},en:{day:'DAY',night:'NIGHT',interact:'TALK / USE',objective:'CURRENT OBJECTIVE',switch:'Change language'}};
  function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*d);canvas.height=Math.floor(r.height*d);ctx.setTransform(d,0,0,d,0,0)}
  new ResizeObserver(resize).observe(canvas);
  function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>t.classList.remove('show'),2100)}
  function save(){try{localStorage.setItem('incursio-save',JSON.stringify({raid:state.raid,hero:state.hero,agatha:state.agatha,free:state.free,weapon:state.weapon,preset:state.preset}))}catch{} $('#footer-status').innerHTML='GUARDADO LOCALMENTE <i>●</i>'}
  function load(){try{const a=JSON.parse(localStorage.getItem('incursio-save')||'null');if(a){state.raid=a.raid||1;state.hero={...state.hero,...a.hero};state.agatha=!!a.agatha;state.free=!!a.free;state.weapon=a.weapon||0;state.preset=a.preset||0}}catch{}}
  load();
  function setObjective(s){$('#objective-text').textContent=s}
  function sync(){const h=state.hero;$('#hero-name').textContent=h.name;$('#hp-text').textContent=`${Math.ceil(h.hp)} / ${h.maxHp}`;$('#hp-fill').style.width=`${Math.max(0,h.hp/h.maxHp*100)}%`;$('#faith-text').textContent=`${h.faith>0?'+':''}${h.faith}%`;$('#faith-fill').style.left=h.faith<0?`${50+h.faith/2}%`:'50%';$('#faith-fill').style.width=`${Math.abs(h.faith)/2}%`;$('#weapon-name').textContent=weapons[state.weapon][0];$('#weapon-preset').textContent=`${weapons[state.weapon][1]} · PRESET 0${state.preset+1}/05`;$('#raid-count').innerHTML=`${String(Math.min(state.raid,8)).padStart(2,'0')} <i>/ 08</i>`;$('#raid-name').textContent=raids[Math.min(state.raid-1,7)];$('#raid-progress').style.width=`${state.kills/(state.raid>=8?3:2)*100}%`;$('#raid-rank').textContent=state.rank;$('#chapter-label').textContent=`${state.phase==='day'?'DÍA':'NOCHE'} ${state.day} · ${state.phase==='day'?'LA ALDEA':`INCURSIÓN ${String(state.raid).padStart(2,'0')}`}`;$('#time-chip').textContent=state.phase==='day'?'☼ DÍA':'☾ NOCHE';$('#location-sub').textContent=state.phase==='day'?'LA ALDEA · MEDIODÍA':`${raids[Math.min(state.raid-1,7)]} · NOCHE`;$('#location-name').textContent=state.phase==='day'?'SANTA VELA':`TIERRAS EXTERIORES`;$('#scene-caption').classList.toggle('hidden',state.phase==='night');$('#boss-banner').classList.toggle('hidden',!state.enemies.some(e=>e.boss));if(state.enemies.some(e=>e.boss))$('#boss-name').textContent=bosses[Math.min(state.raid-1,7)];$('#touch-interact').classList.toggle('hidden',state.phase==='night');$('#scene-frame').classList.toggle('combat',state.phase==='night');}
  function openModal(eyebrow,title,body,actions=[]){state.modal=true;const c=$('#modal-content');c.innerHTML=`<div class="modal-eyebrow">${eyebrow}</div><h2>${title}</h2><div class="modal-body">${body}</div><div class="modal-actions">${actions.map((a,i)=>`<button class="action-btn ${i===0?'primary':'secondary'}" data-choice="${i}">${a.label}</button>`).join('')}</div>`;$('#modal-backdrop').classList.remove('hidden');c.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>actions[+b.dataset.choice].run());}
  function closeModal(){state.modal=false;$('#modal-backdrop').classList.add('hidden')}
  $('#modal-close').onclick=closeModal;$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')closeModal()};
  function talkAgatha(){if(!state.agatha){state.agatha=true;state.hero.faith=Math.min(100,state.hero.faith+15);save();sync();openModal('SANTA VELA · IGLESIA','Hermana Agatha',`<p>«Llegaste justo antes del toque de queda. La oscuridad está probando las puertas, y los aldeanos ya no recuerdan sus propias plegarias.»</p><p>Agatha te entrega una hoz marcada con sal. <b>La primera incursión aguarda al norte.</b></p>`,[{label:'ACEPTAR LA VIGILIA',run:()=>{closeModal();setObjective('Ve a la puerta norte y comienza la incursión');toast('FE +15 · Hoz de vigilia recibida')}}]);}else{openModal('SANTA VELA · IGLESIA','Hermana Agatha',`<p>«La fe no es ausencia de miedo, caminante. Es seguir adelante con él.»</p><p>Tu fe actual: <b>${state.hero.faith > 0?'+':''}${state.hero.faith}%</b>. Los finales dependen de lo que elijas proteger.</p>`,[{label:'AMÉN',run:closeModal},{label:'PEDIR BENDICIÓN (+10 FE)',run:()=>{state.hero.faith=Math.min(100,state.hero.faith+10);sync();save();closeModal();toast('Bendición recibida · FE +10')}}]);}}
