  function interact(){if(state.modal)return;if(state.phase==='day'){if(!state.agatha){talkAgatha();return}const near=[['iglesia',.29,.34],['forja',.71,.32],['botica',.82,.54],['puerta',.5,.12]];const found=near.find(([,x,y])=>Math.hypot(x-state.hero.x,y-state.hero.y)<.2);if(found)buildingAction(found[0]);else {const agathaPos={x:.29,y:.34};if(Math.hypot(agathaPos.x-state.hero.x,agathaPos.y-state.hero.y)<.33)talkAgatha();else toast('Acércate a una persona o edificio')}}}
