  function draw(){const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;ctx.clearRect(0,0,w,h);if(state.phase==='day')drawDay(w,h);else drawNight(w,h);requestAnimationFrame(draw)}
