    // glowing gate landmark
    ctx.strokeStyle='#907e52';ctx.lineWidth=3;ctx.strokeRect(w*.45,h*.42,w*.11,h*.19);ctx.fillStyle='#c09d5b';ctx.fillRect(w*.48,h*.51,3,3);ctx.fillRect(w*.53,h*.48,3,3);
    state.enemies.forEach(e=>{if(e.dead)return;drawEnemy(e,w,h)});drawPerson(w*state.hero.x,h*state.hero.y,'#c3b996',1,true);if(state.invuln>0){ctx.strokeStyle='#ddc078aa';ctx.lineWidth=2;ctx.beginPath();ctx.arc(w*state.hero.x,h*state.hero.y-17,20,0,Math.PI*2);ctx.stroke()}
    // hit bars
    state.enemies.filter(e=>e.boss&&!e.dead).forEach(e=>{ctx.fillStyle='#080909aa';ctx.fillRect(w*.25,h*.13,w*.5,6);ctx.fillStyle='#a75b4b';ctx.fillRect(w*.25,h*.13,w*.5*Math.max(0,e.hp/e.max),6)});
  }
  function drawEnemy(e,w,h){const x=e.x*w,y=e.y*h,s=e.size*(w/800),pulse=1+Math.sin(performance.now()/180+e.x*9)*.06;ctx.save();ctx.translate(x,y);ctx.scale(pulse,pulse);if(e.boss){let glow=ctx.createRadialGradient(0,-12,2,0,-12,s*2.7);glow.addColorStop(0,'#d0785966');glow.addColorStop(1,'#8e272000');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,-12,s*2.7,0,Math.PI*2);ctx.fill()}ctx.fillStyle=e.boss?'#352725':'#26302d';ctx.beginPath();ctx.ellipse(0,-s*.55,s*.62,s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=e.boss?'#bd5846':'#b6b28a';ctx.fillRect(-s*.3,-s*.8,s*.14,3);ctx.fillRect(s*.16,-s*.8,s*.14,3);ctx.strokeStyle=e.boss?'#a56b51':'#59635a';ctx.lineWidth=e.boss?4:2;ctx.beginPath();ctx.moveTo(-s*.3,-s*.1);ctx.lineTo(-s*.65,s*.45);ctx.moveTo(s*.3,-s*.1);ctx.lineTo(s*.65,s*.45);ctx.stroke();ctx.restore()}
  function update(dt){if(state.paused||state.modal)return;if(state.invuln>0)state.invuln-=dt;if(state.phase==='day'){let m=movement();state.hero.x=Math.max(.08,Math.min(.92,state.hero.x+m.x*dt*.33));state.hero.y=Math.max(.35,Math.min(.85,state.hero.y+m.y*dt*.33));return}let m=movement();state.hero.x=Math.max(.06,Math.min(.94,state.hero.x+m.x*dt*.46));state.hero.y=Math.max(.43,Math.min(.89,state.hero.y+m.y*dt*.42));state.enemies.forEach(e=>{if(e.dead)return;let dx=state.hero.x-e.x,dy=state.hero.y-e.y,d=Math.hypot(dx,dy);if(d>.1){e.x+=dx/d*e.speed*dt*2;e.y+=dy/d*e.speed*dt*2}else{e.attack-=dt;if(e.attack<=0&&state.invuln<=0){e.attack=e.boss?1.2:1.55;state.hero.hp-=e.boss?17:10;state.hero.faith=Math.max(-100,state.hero.faith-2);flash();if(state.hero.hp<=0){state.hero.hp=55;state.hero.faith=Math.max(-100,state.hero.faith-12);state.hero.x=.5;state.hero.y=.8;toast('Caíste, pero la campana te devolvió al camino')}}}});state.combatTimer+=dt;state.interactCooldown+=dt;if(state.enemies.length===0&&state.combatTimer>2){state.enemies.push(makeEnemy(false),makeEnemy(false))}sync()}
  let last=performance.now();function loop(now){let dt=Math.min(.05,(now-last)/1000);last=now;update(dt);requestAnimationFrame(loop)}
  resize();sync();requestAnimationFrame(draw);requestAnimationFrame(loop);
  // First-arrival story intro
  if(!state.agatha&&!localStorage.getItem('incursio-intro')){localStorage.setItem('incursio-intro','1');setTimeout(()=>openModal('AÑO 1897 · LOS CÁRPATOS','La última vigilia',`<p>En Santa Vela, la campana ha sonado tres veces sin que nadie toque la cuerda.</p><p>El bosque se ha tragado a dos aldeanos. La Hermana Agatha aguarda en la iglesia. <b>La noche no tardará.</b></p>`,[{label:'ENTRAR EN SANTA VELA',run:()=>{closeModal();setObjective('Habla con la Hermana Agatha')}}]),350)}
})();

