(()=>{
const $=s=>document.querySelector(s), canvas=$('#scene'),ctx=canvas.getContext('2d');
const weapons=[['HOZ DE VIGILIA','PRESAGIO'],['ESPADA DE CENIZA','PURIFICACIÓN'],['MARTILLO DE CAMPANA','RESONANCIA'],['DAGAS DEL PENITENTE','LAMENTO'],['LÁTIGO DE ESPINAS','SACRIFICIO'],['ESTACA DE PLATA','LUCERO'],['LIBRO DE SALMOS','LETANÍA'],['GUADAÑA DEL ABISMO','ÚLTIMO RITO']], raids=['EL BOSQUE QUE RESPIRA','LA CRIPTA SUMERGIDA','EL MOLINO ROJO','EL CAMINO DE LOS CUERVOS','LA MINA DE LOS LAMENTOS','EL PUEBLO ENTERRADO','EL MONASTERIO CIEGO','EL ABISMO'], bosses=['EL ABAD HUECO','LA NOVIA DE BARRO','EL MOLINERO','EL CIERVO NEGRO','LA MADRE DE LA MINA','EL PEREGRINO ROTO','EL SANTO CIEGO','EL ABISMO'];
const state={phase:'day',day:1,raid:1,hero:{x:.5,y:.65,hp:100,maxHp:100,faith:20,name:'EL PEREGRINO'},enemies:[],kills:0,agatha:false,weapon:0,preset:0,paused:false,modal:false,free:false,attacks:0,rank:'—',invuln:0,keys:{},stick:{x:0,y:0}};
try{Object.assign(state,JSON.parse(localStorage.getItem('incursio-save')||'{}'))}catch{};state.hero=Object.assign({x:.5,y:.65,hp:100,maxHp:100,faith:20,name:'EL PEREGRINO'},state.hero||{});
const buildings={iglesia:['Iglesia de Santa Vela','Hermana Agatha espera junto al altar. La campana no ha dejado de vibrar desde el alba.'],forja:['Forja de Iván','El herrero afila tu arma. Cada incursión deja una marca nueva en el acero.'],botica:['Botica de Mara','Frascos de ajenjo y sal consagrada. Recuperas 20 puntos de vitalidad.'],posada:['La Última Posada','El fuego está encendido. Los viajeros hablan de luces bajo el bosque.'],archivo:['Archivo parroquial','Un mapa viejo señala ocho lugares donde la tierra se ha abierto.'],cementerio:['Cementerio','Las lápidas más recientes están vacías. La tierra removida aún está tibia.'],mercado:['Mercado','La gente intercambia pan, velas y rumores. Nada tiene un precio esta noche.'],establo:['Establo','Tu caballo, Ceniza, conoce el camino a la frontera.'],puerta:['Puerta norte','Más allá de la empalizada, el bosque contiene el aliento.']};
function save(){try{localStorage.setItem('incursio-save',JSON.stringify({raid:state.raid,hero:state.hero,agatha:state.agatha,free:state.free,weapon:state.weapon,preset:state.preset}))}catch{}$('#footer-status').innerHTML='GUARDADO LOCALMENTE <i>●</i>'}
function toast(m){let e=$('#toast');e.textContent=m;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),2100)}
function sync(){let h=state.hero;$('#hero-name').textContent=h.name;$('#hp-text').textContent=`${Math.ceil(h.hp)} / ${h.maxHp}`;$('#hp-fill').style.width=`${h.hp}%`;$('#faith-text').textContent=`${h.faith>0?'+':''}${h.faith}%`;$('#faith-fill').style.left=h.faith<0?`${50+h.faith/2}%`:'50%';$('#faith-fill').style.width=`${Math.abs(h.faith)/2}%`;$('#weapon-name').textContent=weapons[state.weapon][0];$('#weapon-preset').textContent=`${weapons[state.weapon][1]} · PRESET 0${state.preset+1}/05`;$('#raid-count').innerHTML=`${String(Math.min(state.raid,8)).padStart(2,'0')} <i>/ 08</i>`;$('#raid-name').textContent=raids[Math.min(state.raid-1,7)];$('#raid-progress').style.width=`${state.kills*35}%`;$('#raid-rank').textContent=state.rank;$('#chapter-label').textContent=`${state.phase==='day'?'DÍA':'NOCHE'} ${state.day} · ${state.phase==='day'?'LA ALDEA':`INCURSIÓN ${state.raid}`}`;$('#time-chip').textContent=state.phase==='day'?'☼ DÍA':'☾ NOCHE';$('#location-sub').textContent=state.phase==='day'?'LA ALDEA · MEDIODÍA':`${raids[Math.min(state.raid-1,7)]} · NOCHE`;$('#location-name').textContent=state.phase==='day'?'SANTA VELA':'TIERRAS EXTERIORES';$('#scene-caption').classList.toggle('hidden',state.phase==='night');$('#boss-banner').classList.toggle('hidden',!state.enemies.some(e=>e.boss&&!e.dead));$('#touch-interact').classList.toggle('hidden',state.phase==='night')}
function modal(eyebrow,title,body,actions=[]){state.modal=true;let c=$('#modal-content');c.innerHTML=`<div class="modal-eyebrow">${eyebrow}</div><h2>${title}</h2><div>${body}</div><div class="modal-actions">${actions.map((a,i)=>`<button class="action-btn ${i?'secondary':'primary'}" data-c="${i}">${a.label}</button>`).join('')}</div>`;$('#modal-backdrop').classList.remove('hidden');c.querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>actions[+b.dataset.c].run())}
function close(){state.modal=false;$('#modal-backdrop').classList.add('hidden')}$('#modal-close').onclick=close;$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')close()};

function agatha(){if(!state.agatha){state.agatha=true;state.hero.faith=Math.min(100,state.hero.faith+15);save();sync();modal('SANTA VELA · IGLESIA','Hermana Agatha',`<p>«Llegaste justo antes del toque de queda. La oscuridad está probando las puertas, y los aldeanos ya no recuerdan sus propias plegarias.»</p><p>Agatha te entrega una hoz marcada con sal. <b>La primera incursión aguarda al norte.</b></p>`,[{label:'ACEPTAR LA VIGILIA',run:()=>{close();objective('Ve a la puerta norte y comienza la incursión');toast('FE +15 · Hoz de vigilia recibida')}}])}else modal('SANTA VELA · IGLESIA','Hermana Agatha',`<p>«La fe no es ausencia de miedo, caminante. Es seguir adelante con él.»</p><p>Tu fe actual: <b>${state.hero.faith>0?'+':''}${state.hero.faith}%</b>. Los finales dependen de lo que elijas proteger.</p>`,[{label:'AMÉN',run:close},{label:'PEDIR BENDICIÓN (+10 FE)',run:()=>{state.hero.faith=Math.min(100,state.hero.faith+10);sync();save();close();toast('Bendición recibida · FE +10')}}])}
function objective(t){$('#objective-text').textContent=t}
function actionBuilding(id){if(id==='iglesia'){agatha();return}if(id==='botica'){state.hero.hp=Math.min(100,state.hero.hp+20);sync();toast('Ajenjo restauró 20 de vitalidad');return}if(id==='puerta'){if(state.phase==='night'){toast('La puerta permanece cerrada durante la incursión');return}if(!state.agatha){toast('Habla primero con la Hermana Agatha');return}modal('PUERTA NORTE · ÚLTIMA LUZ','¿Cruzar el umbral?',`<p>La campana ha callado. Entra al bosque y derrota a los espíritus y al guardián para volver a Santa Vela.</p>`,[{label:'INICIAR INCURSIÓN',run:()=>{close();startRaid()}},{label:'QUEDARSE',run:close}]);return}if(id==='forja'){modal('SANTA VELA · FORJA','La mesa de armas',`<p>Ocho reliquias, ocho formas de resistir. Cada arma altera el ritmo de tus golpes. Elige la que llevarás a la próxima noche.</p><ul class="modal-list">${weapons.map((w,i)=>`<li data-w="${i}" style="cursor:pointer"><b>${w[0]}</b><span>${w[1]}${i===state.weapon?' · EQUIPADA':''}</span></li>`).join('')}</ul>`,[{label:'LISTO',run:close}]);$('#modal-content').querySelectorAll('[data-w]').forEach(x=>x.onclick=()=>{state.weapon=+x.dataset.w;save();sync();close();toast(`${weapons[state.weapon][0]} equipada`)});return}modal('SANTA VELA · REFUGIO',buildings[id][0],`<p>${buildings[id][1]}</p><p style="color:#b6a477">La aldea tiene nueve lugares seguros. Sus habitantes recuerdan cómo los trataste.</p>`,[{label:'SEGUIR EXPLORANDO',run:close})}
function startRaid(){state.phase='night';state.kills=0;state.rank='—';state.attacks=0;state.hero.x=.5;state.hero.y=.76;state.enemies=[enemy(),enemy()];$('#weather-label').textContent='NIEBLA DENSA';objective('Sobrevive a la incursión · derrota a los espectros');sync();toast(`Incursión ${state.raid} · ${raids[state.raid-1]}`)}
function enemy(boss=false){let n=state.raid;return{x:.15+Math.random()*.7,y:.18+Math.random()*.3,hp:boss?120+n*18:34+n*7,max:boss?120+n*18:34+n*7,speed:boss?.025:.045+Math.random()*.02,size:boss?31:17,boss,attack:0,dead:false}}
function boss(){let b=enemy(true);b.x=.5;b.y=.2;state.enemies.push(b);$('#boss-banner').classList.remove('hidden');$('#boss-name').textContent=bosses[state.raid-1];toast(`${bosses[state.raid-1]} se manifiesta`)}
function flash(){let e=$('#combat-flash');e.classList.remove('hit');void e.offsetWidth;e.classList.add('hit')}
function strike(){if(state.phase!=='night'||state.paused||state.modal)return;state.attacks++;let targets=state.enemies.filter(e=>!e.dead&&Math.hypot(e.x-state.hero.x,e.y-state.hero.y)<.22).sort((a,b)=>Math.hypot(a.x-state.hero.x,a.y-state.hero.y)-Math.hypot(b.x-state.hero.x,b.y-state.hero.y));if(!targets.length){state.hero.faith=Math.max(-100,state.hero.faith-1);return}let e=targets[0];e.hp-=22+(state.hero.faith>50?8:0);state.hero.faith=Math.min(100,state.hero.faith+1);flash();if(e.hp<=0){e.dead=true;state.kills++;if(e.boss){state.rank=state.attacks<20?'S':state.attacks<30?'A':'B';endRaid()}else if(state.kills>=2&&!state.enemies.some(x=>x.boss))boss()}sync()}
function skill(){if(state.phase!=='night'){if(!state.agatha)agatha();else toast('La fe responderá cuando caiga la noche');return}if(state.hero.faith<20){toast('Fe insuficiente · necesitas 20');return}state.hero.faith-=20;state.enemies.forEach(e=>{if(!e.dead&&Math.hypot(e.x-state.hero.x,e.y-state.hero.y)<.44){e.hp-=58;if(e.hp<=0){e.dead=true;state.kills++;if(e.boss)endRaid()}}});flash();toast('EXORCISMO · la luz hiere a los cercanos');if(state.kills>=2&&!state.enemies.some(e=>e.boss&&!e.dead))boss();sync()}
function dodge(){if(state.phase==='night'){state.invuln=.55;const m=move();state.hero.x=Math.max(.07,Math.min(.93,state.hero.x+(m.x||.4)*.13));state.hero.y=Math.max(.17,Math.min(.88,state.hero.y+(m.y||-.3)*.13));toast('Esquiva · invulnerable')}}
function ending(){let e=state.hero.faith>=75?'FINAL RECOMENDADO':state.hero.faith>=30?'FINAL BUENO':state.hero.faith<=-50?'FINAL MALO':'FINAL NEUTRO';modal('EPÍLOGO · SANTA VELA',e,`<p>Al amanecer, la campana suena una última vez. <b>${state.hero.faith>=30?'La aldea sigue en pie. Agatha abre las puertas y la gente vuelve a encender sus hogares.':'El pueblo guarda silencio. Cada quien encuentra su propia forma de seguir adelante.'}</b></p><p>Las ocho incursiones han terminado. Tu fe final: <b>${state.hero.faith>0?'+':''}${state.hero.faith}%</b>. Rango: <b>${state.rank}</b>.</p>`,[{label:'CONTINUAR EN MODO LIBRE',run:()=>{state.free=true;state.raid=1;state.day++;save();close();objective('Modo Libre · explora la aldea y repite cualquier incursión');toast('Modo Libre desbloqueado')}},{label:'REINICIAR PARTIDA',run:()=>{localStorage.removeItem('incursio-save');location.reload()}}])}
function endRaid(){if(state.phase!=='night')return;let finished=state.raid;state.phase='day';state.enemies=[];state.hero.hp=Math.min(100,state.hero.hp+25);state.hero.faith=Math.min(100,state.hero.faith+12);state.day++;state.raid++;save();sync();$('#weather-label').textContent='CIELO CARGADO';objective(state.raid<=8?'Habla con la aldea y prepárate para la próxima incursión':'Decide el destino de Santa Vela');modal(`INCURSIÓN ${String(finished).padStart(2,'0')} · RESULTADOS`,`RANGO ${state.rank}`,`<p>La noche retrocede. <b>${state.kills}</b> amenazas exorcizadas. Vitalidad recuperada; Agatha te espera en la iglesia.</p><p>La aldea recuerda tu regreso. Fe: <b>+${state.hero.faith}%</b></p>`,[{label:state.raid<=8?'VOLVER A SANTA VELA':'VER LOS FINALES',run:()=>{close();if(state.raid>8)ending()}}])}
function interact(){if(state.modal)return;if(state.phase==='day'){if(!state.agatha){agatha();return}let near=[['iglesia',.29,.34],['forja',.71,.32],['botica',.82,.54],['puerta',.5,.12]].find(([,x,y])=>Math.hypot(x-state.hero.x,y-state.hero.y)<.2);if(near)actionBuilding(near[0]);else toast('Acércate a una persona o edificio')}}

function move(){let x=(state.keys.ArrowRight||state.keys.d?1:0)-(state.keys.ArrowLeft||state.keys.a?1:0)+state.stick.x,y=(state.keys.ArrowDown||state.keys.s?1:0)-(state.keys.ArrowUp||state.keys.w?1:0)+state.stick.y,l=Math.hypot(x,y);if(l>1){x/=l;y/=l}return{x,y}}
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();state.keys[e.key]=true;if(e.repeat)return;if(e.key===' '||e.key==='j')strike();if(e.key==='q'||e.key==='f')skill();if(e.key==='x'||e.key==='Shift')dodge();if(e.key==='e'||e.key==='Enter')interact();if(e.key==='Escape')pause()});window.addEventListener('keyup',e=>state.keys[e.key]=false);
function trigger(a){if(a==='attack')strike();if(a==='skill')skill();if(a==='dodge')dodge();if(a==='interact')interact()}document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();trigger(b.dataset.action)}));
const stick=$('#move-stick'),knob=stick.querySelector('.stick-knob');let pointer=null;stick.addEventListener('pointerdown',e=>{pointer=e.pointerId;stick.setPointerCapture(pointer);moveStick(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===pointer)moveStick(e)});stick.addEventListener('pointerup',e=>{if(e.pointerId===pointer){pointer=null;state.stick={x:0,y:0};knob.style.transform='translate(-50%,-50%)'}});function moveStick(e){let r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,max=r.width*.34,d=Math.min(max,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);state.stick={x:Math.cos(a)*d/max,y:Math.sin(a)*d/max};knob.style.transform=`translate(calc(-50% + ${Math.cos(a)*d}px),calc(-50% + ${Math.sin(a)*d}px))`}
function pause(){if(state.modal){close();return}state.paused=true;modal('PAUSA · VIGILIA',state.phase==='night'?'La noche espera.':'El día sigue su curso.',`<p>Controles: <b>WASD</b> mover · <b>Espacio</b> atacar · <b>Q</b> exorcismo · <b>Shift</b> esquivar · <b>E</b> interactuar.</p><p>Tu progreso se guarda localmente en este dispositivo.</p>`,[{label:'VOLVER AL JUEGO',run:()=>{state.paused=false;close()}},{label:'GUARDAR',run:()=>{save();state.paused=false;close();toast('Progreso guardado')}}])}$('#pause-btn').onclick=pause;
$('#loadout-btn').onclick=()=>modal('ARSENAL · 8 ARMAS','Tu juramento, tu arma',`<p>Elige una de las ocho reliquias. Cada arma posee un ritmo propio y cinco presets.</p><ul class="modal-list">${weapons.map((w,i)=>`<li data-w="${i}" style="cursor:pointer"><b>${w[0]}</b><span>${w[1]}${i===state.weapon?' · EQUIPADA':''}</span></li>`).join('')}</ul>`,[{label:'CERRAR',run:close}]);$('#weapon-card').onclick=()=>{state.preset=(state.preset+1)%5;sync();save();toast(`Preset ${state.preset+1} · habilidades configuradas`)};
$('#journal-btn').onclick=()=>modal('DIARIO DEL PEREGRINO','Ocho lugares. Una sola noche.',`<p><b>Encargo:</b> Las campanas de Santa Vela suenan sin mano humana. Explora las incursiones, descubre quién llama desde el subsuelo y protege a quienes aún recuerdan tu nombre.</p><ul class="modal-list">${raids.map((r,i)=>`<li>${i+1} · ${r}<span>${state.raid>i+1?'SUPERADA':state.raid===i+1?'ACTUAL':'BLOQUEADA'}</span></li>`).join('')}<li>Hermana Agatha<span>${state.agatha?'ALIADA':'PENDIENTE'}</span></li></ul>`,[{label:'CERRAR DIARIO',run:close}]);
$('#rename-btn').onclick=()=>modal('PERSONALIZACIÓN','Tu nombre, tu vigilia',`<p>Escribe el nombre que la aldea recordará (máximo 18 caracteres).</p><input id="name-input" maxlength="18" value="${state.hero.name}" style="width:100%;margin-top:8px;padding:11px;background:#111;border:1px solid #554b39;color:#eee;font:11px 'DM Mono',monospace">`,[{label:'CONFIRMAR',run:()=>{let v=$('#name-input').value.trim().toUpperCase();if(v)state.hero.name=v.slice(0,18);sync();save();close()}},{label:'CANCELAR',run:close}]);
$('#settings-btn').onclick=()=>modal('AJUSTES · DISPOSITIVO','Una vigilia a tu medida',`<ul class="modal-list"><li>Idioma <span>ESPAÑOL / ENGLISH</span></li><li>Audio ambiente <span>AMBIENTAL</span></li><li>Controles <span>TACTO + TECLADO</span></li><li>Rendimiento <span>AUTO · 60 FPS</span></li></ul><p>Los controles táctiles aparecen en móvil. Conecta un mando Bluetooth compatible para jugar.</p>`,[{label:'CERRAR',run:close}]);$('#language-btn').onclick=()=>{let l=$('#language-btn');l.innerHTML=(l.textContent.trim().startsWith('ES')?'EN':'ES')+' <span>⌄</span>';toast(l.textContent.startsWith('EN')?'Language: English':'Idioma: Español')};$('#sound-btn').onclick=()=>toast('Audio ambiente');document.querySelectorAll('.ability').forEach((a,i)=>a.onclick=()=>i===0?strike():i===1?(state.invuln=.45,toast('Voto de defensa · guardia alzada')):i===2?skill():dodge());

