(()=>{
'use strict';
const $=s=>document.querySelector(s), canvas=$('#scene'),ctx=canvas.getContext('2d');
const weapons=[['HOZ DE VIGILIA','PRESAGIO'],['ESPADA DE CENIZA','PURIFICACIÓN'],['MARTILLO DE CAMPANA','RESONANCIA'],['DAGAS DEL PENITENTE','LAMENTO'],['LÁTIGO DE ESPINAS','SACRIFICIO'],['ESTACA DE PLATA','LUCERO'],['LIBRO DE SALMOS','LETANÍA'],['GUADAÑA DEL ABISMO','ÚLTIMO RITO']];
const raids=['EL BOSQUE QUE RESPIRA','LA CRIPTA SUMERGIDA','EL MOLINO ROJO','EL CAMINO DE LOS CUERVOS','LA MINA DE LOS LAMENTOS','EL PUEBLO ENTERRADO','EL MONASTERIO CIEGO','EL ABISMO'];
const bosses=['EL ABAD HUECO','LA NOVIA DE BARRO','EL MOLINERO','EL CIERVO NEGRO','LA MADRE DE LA MINA','EL PEREGRINO ROTO','EL SANTO CIEGO','EL ABISMO'];
const buildings={iglesia:['Iglesia de Santa Vela','Hermana Agatha espera junto al altar. La campana no ha dejado de vibrar desde el alba.'],forja:['Forja de Iván','El herrero afila tu arma. Cada incursión deja una marca nueva en el acero.'],botica:['Botica de Mara','Frascos de ajenjo y sal consagrada. Recuperas 20 puntos de vitalidad.'],posada:['La Última Posada','El fuego está encendido. Los viajeros hablan de luces bajo el bosque.'],archivo:['Archivo parroquial','Un mapa viejo señala ocho lugares donde la tierra se ha abierto.'],cementerio:['Cementerio','Las lápidas más recientes están vacías. La tierra removida aún está tibia.'],mercado:['Mercado','La gente intercambia pan, velas y rumores. Nada tiene un precio esta noche.'],establo:['Establo','Tu caballo, Ceniza, conoce el camino a la frontera.'],puerta:['Puerta norte','Más allá de la empalizada, el bosque contiene el aliento.']};
const state={phase:'day',day:1,raid:1,hero:{x:.5,y:.65,hp:100,maxHp:100,faith:20,name:'EL PEREGRINO'},enemies:[],kills:0,agatha:false,weapon:0,preset:0,paused:false,modal:false,free:false,attacks:0,rank:'—',invuln:0,keys:{},stick:{x:0,y:0},combo:0,lastAttack:0,lang:'es',sound:true};
try{const d=JSON.parse(localStorage.getItem('incursio-save')||'null');if(d)Object.assign(state,d)}catch{} state.hero=Object.assign({x:.5,y:.65,hp:100,maxHp:100,faith:20,name:'EL PEREGRINO'},state.hero||{});state.enemies=[];state.phase='day';state.paused=false;state.modal=false;
function save(){try{localStorage.setItem('incursio-save',JSON.stringify({raid:state.raid,day:state.day,hero:state.hero,agatha:state.agatha,free:state.free,weapon:state.weapon,preset:state.preset}))}catch{}$('#footer-status').innerHTML='GUARDADO LOCALMENTE <i>●</i>'}
function toast(m){const e=$('#toast');e.textContent=m;e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2100)}
function objective(t){$('#objective-text').textContent=t}
function sync(){const h=state.hero;$('#hero-name').textContent=h.name;$('#hp-text').textContent=`${Math.ceil(h.hp)} / ${h.maxHp}`;$('#hp-fill').style.width=`${Math.max(0,h.hp/h.maxHp*100)}%`;$('#faith-text').textContent=`${h.faith>0?'+':''}${Math.round(h.faith)}%`;$('#faith-fill').style.left=h.faith<0?`${50+h.faith/2}%`:'50%';$('#faith-fill').style.width=`${Math.abs(h.faith)/2}%`;$('#weapon-name').textContent=weapons[state.weapon][0];$('#weapon-preset').textContent=`${weapons[state.weapon][1]} · PRESET 0${state.preset+1}/05`;$('#raid-count').innerHTML=`${String(Math.min(state.raid,8)).padStart(2,'0')} <i>/ 08</i>`;$('#raid-name').textContent=raids[Math.min(state.raid-1,7)];$('#raid-progress').style.width=`${Math.min(100,state.kills*35)}%`;$('#raid-rank').textContent=state.rank;$('#chapter-label').textContent=`${state.phase==='day'?'DÍA':'NOCHE'} ${state.day} · ${state.phase==='day'?'LA ALDEA':`INCURSIÓN ${String(state.raid).padStart(2,'0')}`}`;$('#time-chip').textContent=state.phase==='day'?'☼ DÍA':'☾ NOCHE';$('#location-sub').textContent=state.phase==='day'?'LA ALDEA · MEDIODÍA':`${raids[Math.min(state.raid-1,7)]} · NOCHE`;$('#location-name').textContent=state.phase==='day'?'SANTA VELA':'TIERRAS EXTERIORES';$('#scene-caption').classList.toggle('hidden',state.phase==='night');$('#boss-banner').classList.toggle('hidden',!state.enemies.some(e=>e.boss&&!e.dead));$('#touch-interact').classList.toggle('hidden',state.phase==='night')}
function modal(eyebrow,title,body,actions=[]){state.modal=true;const c=$('#modal-content');c.innerHTML=`<div class="modal-eyebrow">${eyebrow}</div><h2>${title}</h2><div class="modal-body">${body}</div><div class="modal-actions">${actions.map((a,i)=>`<button class="action-btn ${i===0?'primary':'secondary'}" data-choice="${i}">${a.label}</button>`).join('')}</div>`;$('#modal-backdrop').classList.remove('hidden');c.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>actions[+b.dataset.choice].run())}
function close(){state.modal=false;$('#modal-backdrop').classList.add('hidden')}$('#modal-close').onclick=close;$('#modal-backdrop').onclick=e=>{if(e.target.id==='modal-backdrop')close()};
