function talkAgatha(){if(!state.agatha){state.agatha=true;state.hero.faith=Math.min(100,state.hero.faith+15);save();sync();modal('SANTA VELA · IGLESIA','Hermana Agatha',`<p>«Llegaste justo antes del toque de queda. La oscuridad está probando las puertas, y los aldeanos ya no recuerdan sus propias plegarias.»</p><p>Agatha te entrega una hoz marcada con sal. <b>La primera incursión aguarda al norte.</b></p>`,[{label:'ACEPTAR LA VIGILIA',run:()=>{close();objective('Ve a la puerta norte y comienza la incursión');toast('FE +15 · Hoz de vigilia recibida')}}])}else modal('SANTA VELA · IGLESIA','Hermana Agatha',`<p>«La fe no es ausencia de miedo, caminante. Es seguir adelante con él.»</p><p>Tu fe actual: <b>${state.hero.faith>0?'+':''}${state.hero.faith}%</b>. Los finales dependen de lo que elijas proteger.</p>`,[{label:'AMÉN',run:close},{label:'PEDIR BENDICIÓN (+10 FE)',run:()=>{state.hero.faith=Math.min(100,state.hero.faith+10);sync();save();close();toast('Bendición recibida · FE +10')}}])}
function interactBuilding(id){if(state.phase==='night'){toast('No puedes volver a la aldea durante la incursión');return}if(id==='iglesia'){talkAgatha();return}const [name,text]=buildings[id]||buildings.iglesia;let actions=[{label:'SEGUIR',run:close}];if(id==='botica')actions.unshift({label:'TOMAR TÓNICO (+20)',run:()=>{state.hero.hp=Math.min(state.hero.maxHp,state.hero.hp+20);sync();save();close();toast('Vitalidad restaurada')}});if(id==='forja')actions.unshift({label:'AFILAR · CAMBIAR ARMA',run:()=>{close();weaponMenu()}});if(id==='archivo')actions.unshift({label:'LEER EL DIARIO',run:()=>{close();journal()}});if(id==='puerta')actions.unshift({label:state.agatha?'PARTIR A LA INCURSIÓN':'ESPERAR A AGATHA',run:()=>{if(!state.agatha){close();toast('Primero habla con la Hermana Agatha')}else startRaid()}});if(id==='establo')actions.unshift({label:'PARTIR A LA INCURSIÓN',run:()=>{if(state.agatha)startRaid();else{close();toast('Habla primero con Agatha')}}});modal('SANTA VELA · REFUGIO',name,`<p>${text}</p>`,actions)}
function startRaid(){close();state.phase='night';state.hero.x=.5;state.hero.y=.76;state.kills=0;state.enemies=[];state.invuln=0;spawnEnemy(true);for(let i=0;i<2+Math.min(state.raid,4);i++)spawnEnemy(false);objective(`Derrota a las criaturas y encuentra al ${bosses[state.raid-1]}`);sync();save();toast(`${raids[state.raid-1]} · La incursión comienza`)}
function spawnEnemy(boss){const edge=Math.random()<.5?0.08:.92;state.enemies.push({x:edge,y:.25+Math.random()*.55,hp:boss?100+state.raid*24:28+state.raid*5,maxHp:boss?100+state.raid*24:28+state.raid*5,speed:boss?.025:.045+Math.random()*.015,boss,dead:false,hit:0,phase:Math.random()*6})}
function strike(){if(state.paused||state.modal)return;if(state.phase!=='night'){toast('La vigilia aguarda al caer la noche');return}const now=performance.now();if(now-state.lastAttack<360)return;state.lastAttack=now;state.attacks++;state.combo=state.combo%3+1;$('#combat-flash').classList.add('flash');setTimeout(()=>$('#combat-flash').classList.remove('flash'),100);let target=null,dist=.28;for(const e of state.enemies){if(e.dead)continue;const d=Math.hypot(e.x-state.hero.x,e.y-state.hero.y);if(d<dist){dist=d;target=e}}if(target){const dmg=(18+state.weapon*1.7)*(state.combo===3?1.45:1)*(state.hero.faith<0?.85:1);target.hp-=dmg;target.hit=.2;if(target.hp<=0){target.dead=true;state.kills++;state.hero.faith=Math.min(100,state.hero.faith+(target.boss?8:2));toast(target.boss?'¡AMENAZA MAYOR DERROTADA!':'La criatura se deshace en ceniza');if(target.boss)completeRaid()}sync()}else toast(['El golpe corta el aire','No hay nada a tu alcance','Acércate a la criatura'][state.combo-1])}
function skill(){if(state.phase!=='night'){state.hero.faith=Math.min(100,state.hero.faith+3);sync();toast('Una plegaria serena · FE +3');return}if(state.hero.faith<20){toast('Necesitas 20% de fe');return}state.hero.faith-=20;let hit=0;for(const e of state.enemies){if(!e.dead&&Math.hypot(e.x-state.hero.x,e.y-state.hero.y)<.48){e.hp-=48+state.weapon*3;e.hit=.35;hit++;if(e.hp<=0){e.dead=true;state.kills++;state.hero.faith=Math.min(100,state.hero.faith+3);if(e.boss)completeRaid()}}}sync();toast(hit?`Exorcismo · ${hit} criatura${hit>1?'s':''} alcanzada${hit>1?'s':''}`:'El exorcismo ilumina la oscuridad')}
function dodge(){if(state.paused||state.modal)return;const m=move();if(!m.x&&!m.y){state.hero.x=Math.min(.94,Math.max(.06,state.hero.x+.11));}else{state.hero.x=Math.min(.94,Math.max(.06,state.hero.x+m.x*.16));state.hero.y=Math.min(.9,Math.max(.16,state.hero.y+m.y*.16))}state.invuln=.55;toast('Esquiva')}
function completeRaid(){if(state.phase!=='night')return;state.phase='day';state.day++;state.rank=state.kills>=5?'S':state.kills>=3?'A':'B';state.hero.hp=Math.min(state.hero.maxHp,state.hero.hp+25);state.hero.faith=Math.min(100,state.hero.faith+8);state.enemies=[];state.hero.x=.5;state.hero.y=.68;state.raid++;save();sync();if(state.raid>8){endingMenu();return}objective('La aldea está a salvo por ahora. Habla con Agatha o prepara la siguiente incursión.');modal(`INCURSIÓN ${String(state.raid-1).padStart(2,'0')} · COMPLETADA`,'La noche cede',`<p>Sobreviviste a <b>${raids[state.raid-2]}</b> y derrotaste a ${state.kills} criaturas.</p><p>Rango: <b>${state.rank}</b> · Vitalidad recuperada · Fe +8</p><p>Una nueva amenaza aguarda más allá de Santa Vela.</p>`,[{label:'VOLVER A SANTA VELA',run:()=>{close();toast('La aldea te recibe en silencio')}}])}
function endingMenu(){state.raid=8;const high=state.hero.faith>=60,low=state.hero.faith<=-40;const endings=high?['LA LUZ QUE PERMANECE','EL SACRIFICIO SANTO']:low?['REINO DE CENIZA','EL ABISMO HEREDADO']:['LA ÚLTIMA VIGILIA','EL PEREGRINO ERRANTE'];modal('OCHO INCURSIONES · FINAL','La última campana',`<p>El Abismo yace abierto bajo el monasterio. Has sobrevivido a las ocho incursiones, pero aún debes decidir qué hacer con la oscuridad.</p><p>Tu fe: <b>${state.hero.faith>0?'+':''}${state.hero.faith}%</b>. Elige un final; cada decisión queda registrada.</p>`,[{label:endings[0],run:()=>showEnding(endings[0])},{label:endings[1],run:()=>showEnding(endings[1])},{label:'CONTINUAR EN MODO LIBRE',run:()=>{close();state.free=true;state.raid=8;save();toast('Modo libre activado')}}])}
function showEnding(name){state.free=true;save();modal('FINAL · '+name,name,`<p>${name==='LA LUZ QUE PERMANECE'?'La campana suena una vez más. Por primera vez, Santa Vela ve amanecer sin miedo.':name==='REINO DE CENIZA'?'La noche te reconoce como su soberano. Las puertas quedan abiertas, y el mundo contiene el aliento.':'El Abismo se cierra, pero algo de él viaja contigo. Santa Vela vivirá una noche más.'}</p><p><b>Final desbloqueado.</b> Tu vigilia continúa en Modo Libre.</p>`,[{label:'MODO LIBRE',run:()=>{close();state.raid=8;objective('Modo libre: explora la aldea o repite incursiones');sync()}}])}

