function rename(){modal('IDENTIDAD · CAMINANTE','Nombra al peregrino',`<label class="name-field">NOMBRE<input id="name-input" maxlength="18" value="${state.hero.name.replace(/[&<>"']/g,'')}</label>`,[{label:'GUARDAR NOMBRE',run:()=>{const v=$('#name-input').value.trim();if(v)state.hero.name=v.toUpperCase();sync();save();close()}}]);setTimeout(()=>$('#name-input')?.focus(),20)}
function move(){let x=(state.keys.ArrowRight||state.keys.d?1:0)-(state.keys.ArrowLeft||state.keys.a?1:0)+state.stick.x,y=(state.keys.ArrowDown||state.keys.s?1:0)-(state.keys.ArrowUp||state.keys.w?1:0)+state.stick.y;const l=Math.hypot(x,y);if(l>1){x/=l;y/=l}return{x,y}}
function update(dt){if(state.paused||state.modal)return;if(state.phase==='day'){const m=move();state.hero.x=Math.max(.08,Math.min(.92,state.hero.x+m.x*dt*.29));state.hero.y=Math.max(.22,Math.min(.88,state.hero.y+m.y*dt*.25))}else{if(state.invuln>0)state.invuln-=dt;const m=move();state.hero.x=Math.max(.08,Math.min(.92,state.hero.x+m.x*dt*.34));state.hero.y=Math.max(.2,Math.min(.88,state.hero.y+m.y*dt*.3));for(const e of state.enemies){if(e.dead)continue;e.phase+=dt;e.hit=Math.max(0,e.hit-dt);const dx=state.hero.x-e.x,dy=state.hero.y-e.y,d=Math.hypot(dx,dy)||1;e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;if(d<.09&&state.invuln<=0){state.hero.hp-=e.boss?14:7;state.invuln=.9;sync();toast('Herida · esquiva para evitar otro golpe');if(state.hero.hp<=0)gameOver()}}if(!state.enemies.some(e=>e.boss&&!e.dead)&&state.kills<2&&!state.free)spawnEnemy(true)}
}
function gameOver(){state.phase='day';state.enemies=[];state.hero.hp=Math.max(35,Math.ceil(state.hero.maxHp*.45));state.hero.faith=Math.max(-100,state.hero.faith-10);state.hero.x=.5;state.hero.y=.68;sync();save();objective('Recupérate en la Botica y vuelve a intentar la incursión');modal('LA NOCHE TE VENCE','La vigilia no termina aquí',`<p>La criatura te derribó, pero Santa Vela te ha traído de vuelta. Recuperaste parte de tu vitalidad; la incursión puede repetirse.</p>`,[{label:'VOLVER A LA ALDEA',run:close},{label:'REINTENTAR',run:()=>{close();startRaid()}}])}
function interact(){if(state.phase==='night'){toast('Derrota a la amenaza mayor para regresar');return}if(!state.agatha){interactBuilding('iglesia');return}interactBuilding('puerta')}
function setLanguage(){state.lang=state.lang==='es'?'en':'es';$('#language-btn').innerHTML=state.lang.toUpperCase()+' <span>⌄</span>';toast(state.lang==='es'?'Idioma: Español':'Language: Spanish game text remains the default story setting')}
function draw(){const rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=Math.max(1,Math.floor(rect.width*dpr)),h=Math.max(1,Math.floor(rect.height*dpr));if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h}ctx.setTransform(dpr,0,0,dpr,0,0);const W=rect.width,H=rect.height;ctx.clearRect(0,0,W,H);const night=state.phase==='night';const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,night?'#11151d':'#58625d');sky.addColorStop(.58,night?'#27302d':'#84907c');sky.addColorStop(1,night?'#171918':'#383b32');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);ctx.fillStyle=night?'#d8c89b':'#d7c6a0';ctx.globalAlpha=night?.8:.35;ctx.beginPath();ctx.arc(W*.78,H*.19,night?Math.min(W,H)*.07:Math.min(W,H)*.12,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
// distant ridges and tree silhouettes
for(let i=0;i<9;i++){let x=i*W/7-W*.1;ctx.fillStyle=night?'#151b1b':'#485248';ctx.beginPath();ctx.moveTo(x,H*.58);ctx.lineTo(x+W*.13,H*(.22+(i%3)*.06));ctx.lineTo(x+W*.27,H*.58);ctx.fill();ctx.fillStyle=night?'#0c1112':'#343c34';ctx.fillRect(x+W*.1,H*.42,W*.035,H*.31);ctx.beginPath();ctx.moveTo(x+W*.03,H*.47);ctx.lineTo(x+W*.12,H*.22);ctx.lineTo(x+W*.21,H*.47);ctx.fill()}
ctx.fillStyle=night?'#31332d':'#77755f';ctx.beginPath();ctx.moveTo(0,H*.57);ctx.quadraticCurveTo(W*.48,H*.47,W,H*.57);ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();ctx.strokeStyle=night?'#505044':'#a39876';ctx.globalAlpha=.35;for(let i=0;i<12;i++){ctx.beginPath();ctx.moveTo(0,H*(.63+i*.035));ctx.quadraticCurveTo(W*.5,H*(.56+i*.035),W,H*(.64+i*.035));ctx.stroke()}ctx.globalAlpha=1;
if(!night){drawVillage(W,H)}else{for(let i=0;i<8;i++){const x=((i*137+44)%W),y=H*(.25+(i%4)*.1);ctx.fillStyle='#ddaa62';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(x,y,3+i%3,0,7);ctx.fill();ctx.globalAlpha=1}}
for(const e of state.enemies)if(!e.dead)drawEnemy(e,W,H);drawHero(W,H);if(night){ctx.fillStyle='#f0e2c4';ctx.font=`${Math.max(10,W*.018)}px monospace`;ctx.fillText('✣  '+raids[state.raid-1],18,H-22)} }
function drawVillage(W,H){const places=[['iglesia',.48,.43,1.35],['forja',.24,.49,.8],['botica',.74,.5,.75],['posada',.15,.59,.7],['archivo',.83,.58,.72],['cementerio',.1,.42,.55],['mercado',.89,.43,.65],['establo',.34,.55,.7],['puerta',.53,.61,.45]];for(const [id,x,y,s] of places){const bw=W*.105*s,bh=H*.17*s,px=x*W,py=y*H;ctx.fillStyle='#171918';ctx.fillRect(px-bw/2,py-bh*.56,bw,bh*.56);ctx.fillStyle=id==='iglesia'?'#51493d':'#4b453a';ctx.beginPath();ctx.moveTo(px-bw*.6,py-bh*.52);ctx.lineTo(px,py-bh*1.12);ctx.lineTo(px+bw*.6,py-bh*.52);ctx.fill();ctx.fillStyle=id==='iglesia'?'#ba9b63':'#886c50';ctx.fillRect(px-bw*.07,py-bh*.29,bw*.14,bh*.29);if(id==='iglesia'){ctx.fillStyle='#b89b66';ctx.fillRect(px-bw*.025,py-bh*1.35,bw*.05,bh*.28);ctx.fillRect(px-bw*.1,py-bh*1.26,bw*.2,bh*.05)}if(Math.hypot(state.hero.x-x,state.hero.y-y)<.12){ctx.fillStyle='#eee4ce';ctx.font='11px monospace';ctx.textAlign='center';ctx.fillText(id==='iglesia'?'E · HABLAR':id==='puerta'?'E · PARTIR':id.toUpperCase(),px,py-bh*1.2);ctx.textAlign='left}}}

